import { useEffect, useState } from 'react'
import usePaymentByAgent from './usePaymentByAgent'
import usePaymentByCustomer from './usePaymentByCustomer'
import { loadSnapJs } from './helpers'
import { XenditPaymentStyle, IframeContainer } from './index.style'

function XenditPayment({ policy, policyId, stepsHeader, paymentBy }) {
  const [xenditUrl, setXenditUrl] = useState(null)

  const isPaymentByAgent = paymentBy === 'agent'
  const isPaymentByCustomer = paymentBy === 'customer'

  const { isAgentCanPay } = usePaymentByAgent({
    policy,
    policyId,
    isPaymentByAgent,
    setXenditUrl,
  })
  const { isCustomerCanPay } = usePaymentByCustomer({
    policy,
    policyId,
    isPaymentByCustomer,
    setXenditUrl,
  })

  useEffect(() => {
    // Load snapjs for midtrans https://docs.midtrans.com/reference/snap-js
    loadSnapJs()
  }, [])

  return (
    <XenditPaymentStyle>
      <IframeContainer stepsHeader={stepsHeader}>
        {((isPaymentByAgent && isAgentCanPay) ||
          (isPaymentByCustomer && isCustomerCanPay)) &&
          xenditUrl && <iframe src={`${xenditUrl}`} title="Xendit Checkout" />}
      </IframeContainer>
    </XenditPaymentStyle>
  )
}

export default XenditPayment
