import { COMMON_ACTIONS } from './actions'

export const INITIAL_STATE = {
  commonState: {}
}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case COMMON_ACTIONS.GET_CITIES:
    case COMMON_ACTIONS.VALIDATE_CHASSIS_NO:
    case COMMON_ACTIONS.GET_SURVEY_FORM:
    case COMMON_ACTIONS.OFFLINE_QUOTE_DETAIL:
      return {
        ...state,
        ...payload
      }
    case COMMON_ACTIONS.GET_INVOICE_DETAIL:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...state
      }
  }
}
export default reducer
