import { useEffect, useState } from 'react'
import { useHistory } from 'react-router'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../components/ShowNotification/index'
import { checkIsCorporateAgent } from '../../../../../constants/appConstants'
import { useGlobalContextValue } from '../../../../../contextProvider/GlobalContext'
import { LANG_STRINGS } from '../../../../../lang'
import { useValidateChassisNumber } from '../../../../../state/commonState/hooks/useCommonContext'
import {
  useAgentPaying,
  useGeneratePaymentUrl,
} from '../../state/hooks/usePaymentState'
import { calculatePayableAmount, getPreValidateKeys } from './helpers'

function usePaymentByAgent({
  policy,
  policyId,
  isPaymentByAgent,
  setXenditUrl,
}) {
  const history = useHistory()

  const [isAgentPayingReqSent, setIsAgentPayingReqSent] = useState(null)
  const [isAgentCanPay, setIsAgentCanPay] = useState(null)
  const [isPassPreValidate, setIsPassPreValidate] = useState(null)

  const [{ getAgentDetailData }] = useGlobalContextValue()
  const [{ validateChassisNoData = {} }, validateChassisNoRequest] =
    useValidateChassisNumber()
  const [{ agentPayingData }, agentPayingReq] = useAgentPaying()
  const [{ getPaymentUrlData }, generatePaymentUrlReq] = useGeneratePaymentUrl()
  const { resetError } = useResetError()
  const [
    {
      validateChassisNoStatus,
      validateChassisNoErrorData,
      agentPayingStatus,
      agentPayingErrorData,
      getPaymentUrlStatus,
      getPaymentUrlErrorData,
    },
  ] = useErrorContextValue()

  useEffect(() => {
    // If agent ktp is not verified, cannot pay by agent
    if (!isPaymentByAgent || !getAgentDetailData) return

    const isCorporateAgent = checkIsCorporateAgent(getAgentDetailData?.agent_type)
    if (!isCorporateAgent && getAgentDetailData?.is_ktp_verified !== true) {
      ShowSnackbar.error({ text: LANG_STRINGS.yourKtpMustVerifiedForThePayment })
      setIsAgentCanPay(false)
      return
    }
    if (isCorporateAgent && getAgentDetailData?.is_nib_verified !== true) {
      ShowSnackbar.error({ text: LANG_STRINGS.yourNibMustVerifiedForThePayment })
      setIsAgentCanPay(false)
      return
    }
    setIsAgentCanPay(true)
  }, [isPaymentByAgent, getAgentDetailData])

  useEffect(() => {
    if (!isPaymentByAgent || !policy) return

    const params = policy?.product?.pre_validate_params
    if (policy?.policy_detail?.chasis_number && params) {
      // For MV case, pre-validate before allowing user can pay
      validateChassisNoRequest({
        body: {
          code: policy?.code,
          identifier_value: policy?.id?.replaceAll('-', ''),
          identifier: 'reference_id',
          pre_validate_data: getPreValidateKeys(policy?.policy_detail, params),
        },
      })
    } else {
      // For non-MV case, always pass pre-validate
      setIsPassPreValidate(true)
    }
  }, [isPaymentByAgent, policy, validateChassisNoRequest, resetError])

  useEffect(() => {
    // Check response of chasis number pre-validate
    if (!isPaymentByAgent || !validateChassisNoStatus) return

    if (validateChassisNoStatus !== 'success') {
      ShowSnackbar.error({ text: validateChassisNoErrorData?.message })
      resetError(['validateChassisNoStatus'])
      return
    }

    if (!!validateChassisNoData.success) {
      setIsPassPreValidate(true)
    } else {
      ShowSnackbar.error({ text: LANG_STRINGS.chassisNumberPolicyAlreadyExist })
      setIsPassPreValidate(false)
    }
    resetError(['validateChassisNoStatus'])
  }, [
    isPaymentByAgent,
    validateChassisNoStatus,
    validateChassisNoData,
    validateChassisNoErrorData,
    resetError,
  ])

  useEffect(() => {
    // On init, automatically hit /agent-paying API
    if (!isPaymentByAgent || isAgentPayingReqSent === true) return

    const payableAmount = calculatePayableAmount(policy)
    if (policyId && payableAmount > 0 && isPassPreValidate && isAgentCanPay) {
      agentPayingReq({
        policyId,
        body: {
          agent_paying: true,
          payable_amount: payableAmount,
          commission: { amount: 0, tax: 0 }, // this is legacy code, always hardcode to 0
          point: { amount: 0, point: 0, tax: 0 }, // this is legacy code, always hardcode to 0
        },
      })
      setIsAgentPayingReqSent(true)
    }
  }, [
    isPaymentByAgent,
    policyId,
    policy,
    agentPayingReq,
    isAgentPayingReqSent,
    isAgentCanPay,
    isPassPreValidate,
  ])

  useEffect(() => {
    // Once agent-paying is success, automatically hit /generate-token API
    if (!isPaymentByAgent || !agentPayingStatus) return

    if (agentPayingStatus !== 'success') {
      ShowSnackbar.error({ text: agentPayingErrorData?.message })
      resetError(['agentPayingStatus'])
      return
    }

    // Generate payment url here
    const body = {
      payment_gateway: 'xendit',
      // payment_method: 'BANKING', // TODO: update or remove
      // bank_va: 'mandiri', // TODO: update or remove
      transaction_id: agentPayingData.transaction_id,
    }
    generatePaymentUrlReq({ body })
    resetError(['agentPayingStatus'])
  }, [
    history,
    isPaymentByAgent,
    policyId,
    agentPayingStatus,
    agentPayingData,
    agentPayingErrorData,
    generatePaymentUrlReq,
    resetError,
  ])

  useEffect(() => {
    // Check generate token response
    if (!isPaymentByAgent || !getPaymentUrlStatus) return

    if (getPaymentUrlStatus !== 'success') {
      if (
        getPaymentUrlErrorData?.error_code ===
        'PP-PAYMENT-NOT-ALLOWED-AT-THE-MOMENT'
      ) {
        ShowSnackbar.error({ text: getPaymentUrlErrorData?.message })
        resetError(['getPaymentUrlErrorData'])
        history.push(`/transactions/${policyId}/details`)
        return
      }
    }
    const paymentUrl = getPaymentUrlData?.payment_url

    if (paymentUrl) {
      setXenditUrl(paymentUrl)
      resetError(['getPaymentUrlStatus'])
      return
    }
  }, [
    history,
    isPaymentByAgent,
    policyId,
    getPaymentUrlStatus,
    getPaymentUrlData,
    getPaymentUrlErrorData,
    setXenditUrl,
    resetError,
  ])

  return { isAgentCanPay }
}

export default usePaymentByAgent
